const britishConstitutionLandscape={src:"assets/diagrams/post-defeat-british-constitutional-order.svg",alt:"Diagram of the constitutional order of post-defeat Britain",caption:"The Crown, two Houses, responsible Cabinet, courts, and differentiated Commonwealth statuses remain connected without becoming a single written constitution"};
