    sources:[...britishConstitutionSources,{href:"https://www.parliament.uk/business/bills-and-legislation/",label:"UK Parliament — bills, Acts, delegated legislation, and the passage of legislation"},{href:"https://www.parliament.uk/about/how/laws/passage-bill/",label:"UK Parliament — stages through which a bill becomes law"},{href:"https://www.parliament.uk/about/how/publications/bills-acts/",label:"UK Parliament — bill texts, agreed form, royal assent, and Acts"},{href:"https://www.legislation.gov.uk/ukpga/1911/13/pdfs/ukpga_19110013_en.pdf",label:"Legislation.gov.uk — Parliament Act 1911"},{href:"https://www.legislation.gov.uk/ukpga/1931/4/pdfs/ukpga_19310004_en.pdf",label:"Legislation.gov.uk — Statute of Westminster 1931"},{href:"https://commonslibrary.parliament.uk/research-briefings/sn06509/",label:"House of Commons Library — statutory instruments and delegated legislation"}],
